*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page:        #0e0f13;
  --bg-surface:     #16181f;
  --bg-raised:      #1e2029;
  --bg-overlay:     #262932;

  --border:         #2e3140;
  --border-strong:  #3d4155;

  --text-primary:   #f0f1f5;
  --text-secondary: #9da3b4;
  --text-muted:     #8892aa;

  --accent:         #6c8fff;
  --accent-hover:   #8ba5ff;

  --danger:         #e05a5a;
  --danger-hover:   #f07070;
  --danger-bg:      rgba(224, 90, 90, 0.12);

  --focus-ring:     #6c8fff;
  --radius-sm:      6px;
  --radius-md:      10px;
  --radius-lg:      14px;

  --shadow-dialog:  0 24px 60px rgba(0, 0, 0, 0.7), 0 4px 16px rgba(0, 0, 0, 0.5);
}

html {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg-page);
  color: var(--text-primary);
  line-height: 1.6;
}

/* ── Skip link ──────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  font-weight: 600;
  border-radius: var(--radius-sm);
  text-decoration: none;
  z-index: 9999;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 1rem;
}

/* ── Focus ring (global) ────────────────────────────────────── */
:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

/* ── Header ─────────────────────────────────────────────────── */
.site-header {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 1rem 2rem;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border);
}
.site-logo {
  color: var(--accent);
  font-size: 1.2rem;
}
.site-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

/* ── Main layout ─────────────────────────────────────────────── */
.main-content {
  max-width: 860px;
  margin: 2.5rem auto;
  padding: 0 1.5rem 4rem;
}

/* ── Breadcrumb ─────────────────────────────────────────────── */
.breadcrumb ol {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.5rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}
.breadcrumb a {
  color: var(--accent);
  text-decoration: none;
}
.breadcrumb a:hover {
  text-decoration: underline;
}
.breadcrumb li + li::before {
  content: "/";
  margin-right: 0.5rem;
  color: var(--text-muted);
}

/* ── Page heading ───────────────────────────────────────────── */
h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 1.5rem;
  letter-spacing: -0.01em;
}

/* ── Image preview ──────────────────────────────────────────── */
.image-preview {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  line-height: 0;
}
.preview-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 500px;
  object-fit: cover;
}

/* ── Image metadata & actions ───────────────────────────────── */
.image-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1.25rem;
  margin-top: 1.25rem;
  padding: 1.25rem 1.5rem;
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
}

.meta-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 2rem;
}
.meta-item {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}
.meta-list dt {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}
.meta-list dd {
  font-size: 0.9rem;
  color: var(--text-secondary);
}

.image-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

/* ── Buttons ─────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1.25rem;
  font-size: 0.9rem;
  font-weight: 600;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  line-height: 1.4;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;
}
.btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

.btn--secondary {
  background: var(--bg-overlay);
  color: var(--text-primary);
  border-color: var(--border-strong);
}
.btn--secondary:hover {
  background: var(--border-strong);
}

.btn--danger {
  background: var(--danger-bg);
  color: var(--danger);
  border-color: var(--danger);
}
.btn--danger:hover {
  background: var(--danger);
  color: #fff;
}

/* ── Dialog ──────────────────────────────────────────────────── */
dialog {
  /* Reset browser defaults */
  border: none;
  padding: 0;
  background: transparent;
  color: var(--text-primary);
  max-width: min(92vw, 460px);
  width: 100%;
  border-radius: var(--radius-lg);
}

dialog::backdrop {
  background: rgba(0, 0, 0, 0.75);
  backdrop-filter: blur(3px);
}

/* Closed state: hidden from AT and focus order */
dialog:not([open]) {
  display: none;
}

.dialog-inner {
  background: var(--bg-raised);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  padding: 1.75rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.dialog-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.dialog-title {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  line-height: 1.3;
}

.dialog-close {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  background: transparent;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  color: var(--text-secondary);
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
  padding: 0;
