.site-header {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 1rem 2rem;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border);
}
.site-logo {
  color: var(--accent);
  font-size: 1.2rem;
}
.site-name {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  letter-spacing: 0.01em;
}

/* ── Main layout ─────────────────────────────────────────────── */
.main-content {
  max-width: 860px;
  margin: 2.5rem auto;
  padding: 0 1.5rem 4rem;
}

/* ── Breadcrumb ─────────────────────────────────────────────── */
.breadcrumb ol {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0.5rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  margin-bottom: 1.25rem;
}
.breadcrumb a {
  color: var(--accent);
  text-decoration: none;
}
.breadcrumb a:hover {
  text-decoration: underline;
}
.breadcrumb li + li::before {
  content: "/";
  margin-right: 0.5rem;
  color: var(--text-muted);
}

/* ── Page heading ───────────────────────────────────────────── */
h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 1.5rem;
  letter-spacing: -0.01em;
}

/* ── Image preview ──────────────────────────────────────────── */
.image-preview {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  line-height: 0;
}
.preview-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 500px;
  object-fit: cover;
}

