  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

.dialog-body {
  font-size: 0.95rem;
  color: var(--text-secondary);
  line-height: 1.6;
}
.dialog-body strong {
  color: var(--text-primary);
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
  flex-wrap: wrap;
}

