 (function () {
   'use strict';

   const dialog       = document.getElementById('delete-dialog');
   const trigger      = document.getElementById('delete-trigger');
   const cancelBtn    = document.getElementById('cancel-btn');
   const confirmBtn   = document.getElementById('confirm-delete-btn');
   const statusMsg    = document.getElementById('status-message');
   const closeButtons = dialog.querySelectorAll('[data-close]');

   // Open the dialog; focus lands on Cancel (not the destructive action).
   trigger.addEventListener('click', () => {
     dialog.showModal();
     cancelBtn.focus();
   });

   // Close on any [data-close] element (Cancel button, ✕ button).
   closeButtons.forEach((btn) => {
     btn.addEventListener('click', () => dialog.close('cancel'));
   });

   // Confirm deletion.
   confirmBtn.addEventListener('click', () => {
     dialog.close('delete');
   });

   // Handle the dialog result after it closes.
   dialog.addEventListener('close', () => {
     if (dialog.returnValue === 'delete') {
       announce('Image deleted from your library.');
       // In a real app, trigger the delete API call and update the DOM here.
